def clash_score(X):
    frag = list(range(26, len(X)))
    worst=[]
    for i in range(25):
        for j in frag:
            d = np.linalg.norm(X[i]-X[j])
            lim = 1.7 if (i>=13 or atoms[j][0]=='H') else 2.2
            if d < lim: worst.append((round(float(d),2),i,j))
    return sorted(worst)

results=[]
